const tg=window.Telegram?.WebApp;if(tg){tg.ready();tg.expand();tg.setHeaderColor('#080e13');tg.setBackgroundColor('#080e13');tg.BackButton.onClick(()=>navigate('home'));}
const paths={folder:'M3 7h7l3 3h8v10H3z',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',chat:'M4 4h16v13H10l-5 4v-4H4z M8 10h8',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-2a8 6 0 0 1 16 0v2z',file:'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h3',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17h.01',chart:'M5 20v-5 M12 20V9 M19 20V4',shield:'m12 3 9 4v5c0 5-9 10-9 10S3 17 3 12V7z m-5 9 4 4 6-7'};
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[e.dataset.icon]}"/></svg>`);
const projects=[{id:1,name:'Интернет-магазин',type:'Веб',text:'Витрина товаров, корзина и удобное управление заказами.'},{id:2,name:'CRM для команды',type:'Бизнес',text:'Клиенты, сделки и задачи в одном рабочем пространстве.'},{id:3,name:'Telegram-магазин',type:'Telegram',text:'Mini App для продаж прямо внутри мессенджера.'},{id:4,name:'Платформа обучения',type:'Веб',text:'Курсы, уроки и личный кабинет ученика.'},{id:5,name:'Бот записи',type:'Telegram',text:'Расписание и автоматическая запись на услуги.'},{id:6,name:'Аналитика бизнеса',type:'Бизнес',text:'Наглядные отчёты и ключевые показатели компании.'}];
function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}let favorites=read('ph-favorites',[]),requests=read('ph-requests',[]),page='home',filter='Все',query='';let timer;
function save(){try{localStorage.setItem('ph-favorites',JSON.stringify(favorites));localStorage.setItem('ph-requests',JSON.stringify(requests))}catch{toast('Хранилище устройства недоступно')}}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('visible'),3000)}
function escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function cards(){const shown=projects.filter(p=>(page!=='favorites'||favorites.includes(p.id))&&(filter==='Все'||filter===p.type)&&p.name.toLowerCase().includes(query.toLowerCase()));return shown.length?shown.map(p=>`<article class="card"><span class="tag">${p.type} · ДЕМО-КОНЦЕПТ</span><h3>${p.name}</h3><p>${p.text}</p><div class="actions"><button class="secondary" data-project="${p.id}">Обсудить проект →</button><button class="favorite" data-favorite="${p.id}" aria-label="${favorites.includes(p.id)?'Убрать из избранного':'В избранное'}" aria-pressed="${favorites.includes(p.id)}">${favorites.includes(p.id)?'★':'☆'}</button></div></article>`).join(''):'<p class="subtitle">Пока здесь пусто. Добавьте проекты в избранное или измените поиск.</p>'}
function navigate(next,project=''){page=next;document.getElementById('home').hidden=next!=='home';const c=document.getElementById('content');c.hidden=next==='home';if(tg){next==='home'?tg.BackButton.hide():tg.BackButton.show()}if(next==='catalog'||next==='favorites'){filter='Все';query='';c.innerHTML=`<h2>${next==='catalog'?'Каталог проектов':'Избранное'}</h2><p class="subtitle">Выберите основу для своего следующего проекта.</p><input id="search" placeholder="Найти проект…" aria-label="Поиск проектов"><div class="toolbar">${['Все','Веб','Telegram','Бизнес'].map(x=>`<button data-filter="${x}" class="${x==='Все'?'active':''}">${x}</button>`).join('')}</div><div class="projects" id="projects">${cards()}</div>`}if(next==='consult'){c.innerHTML=`<h2>Обсудим вашу идею</h2><p class="subtitle">Расскажите, что вы хотите создать.</p><form class="form" id="request-form"><label>Ваше имя<input name="name" required maxlength="80" autocomplete="name"></label><label>Telegram или телефон<input name="contact" required maxlength="100" placeholder="@username или +7…"></label><label>Проект<input name="project" maxlength="100" value="${escape(project)}" placeholder="Название или направление"></label><label>Описание задачи<textarea name="description" required maxlength="1500" placeholder="Что должно делать приложение?"></textarea></label><p class="notice">${tg?.initData&&!tg.initDataUnsafe?.query_id?'Заявка будет передана боту через Telegram.':'Демо-режим: заявка сохранится только на этом устройстве. Для отправки откройте приложение кнопкой в клавиатуре бота.'}</p><button class="primary" type="submit">${tg?.initData&&!tg.initDataUnsafe?.query_id?'Отправить заявку':'Сохранить черновик'} →</button></form>`}if(next==='requests'){c.innerHTML=`<h2>Мои заявки</h2><p class="subtitle">Локальная история на этом устройстве.</p><div class="projects">${requests.length?requests.map(r=>`<article class="card"><span class="tag">ЧЕРНОВИК · ${new Date(r.date).toLocaleDateString('ru-RU')}</span><h3>${escape(r.project||'Консультация')}</h3><p>${escape(r.description)}</p><small>${escape(r.name)} · ${escape(r.contact)}</small></article>`).join(''):'<div class="card"><h3>Пока нет заявок</h3><p>Расскажите о задаче, чтобы начать работу над проектом.</p><button class="secondary" data-page="consult">Создать заявку →</button></div>'}</div>`}if(next==='about')c.innerHTML='<h2>О ProjectHub</h2><div class="card"><h3>От идеи до работающего продукта</h3><p>Пространство для выбора и обсуждения IT-решений: сайты, бизнес-системы и Telegram-приложения.</p><p>В каталоге представлены демонстрационные концепты. Состав работ, сроки и стоимость согласовываются индивидуально.</p><button class="secondary" data-page="consult">Обсудить задачу →</button></div>';if(next==='help')c.innerHTML='<h2>Помощь</h2><details open><summary>Как выбрать проект?</summary><p>Откройте каталог, найдите подходящее направление и нажмите «Обсудить проект».</p></details><details><summary>Где хранится избранное?</summary><p>Избранное и черновики заявок сохраняются на вашем устройстве. На другом устройстве они не появятся.</p></details><details><summary>Как отправить заявку?</summary><p>После подключения бота откройте приложение кнопкой его клавиатуры. В браузерной демоверсии доступно сохранение черновика.</p></details>';window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)navigate(b.dataset.page);if(b.id==='back')navigate('home');if(b.id==='more')navigate('help');if(b.dataset.project)navigate('consult',projects.find(p=>p.id===Number(b.dataset.project)).name);if(b.dataset.favorite){const id=Number(b.dataset.favorite);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save();document.getElementById('projects').innerHTML=cards()}if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter));document.getElementById('projects').innerHTML=cards()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.getElementById('projects').innerHTML=cards()}});
document.addEventListener('submit',e=>{if(e.target.id!=='request-form')return;e.preventDefault();const r=Object.fromEntries(new FormData(e.target));r.date=new Date().toISOString();const payload=JSON.stringify({type:'request',...r});if(new TextEncoder().encode(payload).length>4000){toast('Сократите описание заявки');return}if(tg?.initData&&!tg.initDataUnsafe?.query_id){try{tg.sendData(payload);return}catch{toast('Не удалось отправить. Сохраняем черновик.')}}requests.unshift(r);save();navigate('requests');toast('Черновик сохранён на устройстве')});
